assert all(len(row)==6 and all(row) for row in source.values())
destination = ROOT/'app/src/main/assets'
destination.mkdir(parents=True,exist_ok=True)
(destination/'catalog.json').write_text(json.dumps(source,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(destination/'LICENSE.txt').write_bytes((ROOT/'LICENSE').read_bytes())
